(q) => {
        const v = q.visual.rows.slice(1).map(r => r[1]).filter(c => c !== '').map(Number);
        return v.reduce((s, x) => s + x, 0) / v.length;
      }

(q) => {
        const range = q.visual.rows.slice(1, 6);
        const row = range.find(r => r[0] === 'P-104');
        const cell = row[3 - 1];
        return typeof cell === 'string' ? Number(cell) : cell.en;
      }

(q) => {
        const g = q.visual.rows;
        const shift = (f, dr, dc) => f.replace(/(\$?)([A-Z])(\$?)(\d+)/g, (m, cA, col, rA, row) =>
          cA + (cA ? col : String.fromCharCode(col.charCodeAt(0) + dc)) + rA + (rA ? row : String(Number(row) + dr)));
        const f = shift(g[1][1], 1, 1);
        const val = ref => { const m = ref.replace(/\$/g, '').match(/([A-Z])(\d+)/); return Number(g[Number(m[2]) - 1][m[1].charCodeAt(0) - 65]); };
        return f.slice(1).split('*').map(val).reduce((a, b) => a * b, 1);
      }

(q) => {
        const g = q.visual.rows;
        const shift = (f, dr, dc) => f.replace(/(\$?)([A-Z])(\$?)(\d+)/g, (m, cA, col, rA, row) =>
          cA + (cA ? col : String.fromCharCode(col.charCodeAt(0) + dc)) + rA + (rA ? row : String(Number(row) + dr)));
        const f = shift(g[2][1], 1, 0);
        const val = ref => { const m = ref.replace(/\$/g, '').match(/([A-Z])(\d+)/); return Number(g[Number(m[2]) - 1][m[1].charCodeAt(0) - 65]); };
        return f.slice(1).split('*').map(val).reduce((a, b) => a * b, 1);
      }

(q) => {
        const inGB = { KB: 1e-6, MB: 1e-3, GB: 1, TB: 1000 };
        let best = null, bestVal = -1;
        for (const opt of q.options) {
          const [n, unit] = opt.split(' ');
          const v = Number(n) * inGB[unit];
          if (v > bestVal) { bestVal = v; best = opt; }
        }
        return best;
      }
